import{_ as t,o as e,c as i,a3 as s}from"./chunks/framework.D1iekJsc.js";const k=JSON.parse('{"title":"安装 ComfyUI","description":"安装 ComfyUI，开启局域网监听，供 MiniTavern 生图连接使用默认 workflow。","frontmatter":{"title":"安装 ComfyUI","description":"安装 ComfyUI，开启局域网监听，供 MiniTavern 生图连接使用默认 workflow。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"安装 ComfyUI · MiniTavern Docs"}],["meta",{"property":"og:description","content":"安装 ComfyUI，开启局域网监听，供 MiniTavern 生图连接使用默认 workflow。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/local/image-gen/comfyui"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/local/image-gen/comfyui"}]]},"headers":[],"relativePath":"local/image-gen/comfyui.md","filePath":"local/image-gen/comfyui.md","lastUpdated":1786517442000}'),n={name:"local/image-gen/comfyui.md"};function o(l,a,r,p,d,h){return e(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="安装-comfyui" tabindex="-1">安装 ComfyUI <a class="header-anchor" href="#安装-comfyui" aria-label="Permalink to &quot;安装 ComfyUI&quot;">​</a></h1><p>ComfyUI 是节点式本地生图前端，对新模型支持较快。<br> MiniTavern 通过 ComfyUI 的 HTTP API（<code>/prompt</code> 等）提交<strong>内置默认工作流</strong>；你无需在 App 里手写节点图即可出图。</p><p>官方文档：<a href="https://docs.comfy.org/" target="_blank" rel="noreferrer">docs.comfy.org</a> · 仓库：<a href="https://github.com/Comfy-Org/ComfyUI" target="_blank" rel="noreferrer">Comfy-Org/ComfyUI</a></p><h2 id="硬件建议" tabindex="-1">硬件建议 <a class="header-anchor" href="#硬件建议" aria-label="Permalink to &quot;硬件建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>显存</th><th>建议</th></tr></thead><tbody><tr><td>6GB</td><td>SD 1.5 等较小工作流</td></tr><tr><td>8–12GB</td><td>SDXL、部分快速 Flux 变体更现实</td></tr><tr><td>Apple Silicon</td><td>可原生跑，一般慢于同级 NVIDIA</td></tr></tbody></table><h2 id="方式-a-windows-便携包-推荐" tabindex="-1">方式 A：Windows 便携包（推荐） <a class="header-anchor" href="#方式-a-windows-便携包-推荐" aria-label="Permalink to &quot;方式 A：Windows 便携包（推荐）&quot;">​</a></h2><ol><li>打开 <a href="https://www.comfy.org/download" target="_blank" rel="noreferrer">ComfyUI 发布页 / 官网下载</a>（或社区提供的 <code>ComfyUI_windows_portable</code> 包）。</li><li>解压到非系统盘路径（路径尽量短、无中文空格亦可）。</li><li>有 NVIDIA 时运行 <code>run_nvidia_gpu.bat</code>；仅 CPU 时用对应 CPU 脚本。</li><li>本机浏览器打开提示的地址，常见为：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8188</span></span></code></pre></div><h2 id="方式-b-desktop-应用" tabindex="-1">方式 B：Desktop 应用 <a class="header-anchor" href="#方式-b-desktop-应用" aria-label="Permalink to &quot;方式 B：Desktop 应用&quot;">​</a></h2><ol><li>安装 <a href="https://docs.comfy.org/" target="_blank" rel="noreferrer">ComfyUI Desktop</a>。</li><li>设置 → Server Configuration（或同类「服务器 / 网络」项）： <ul><li><strong>Listen Address</strong> 改为 <code>0.0.0.0</code>（默认 <code>127.0.0.1</code> 时手机连不上）</li><li>记下 <strong>Port</strong>（Desktop 常见 <strong>8000</strong>，与便携版 8188 不同）</li></ul></li><li>重启后再用局域网 IP 访问。</li></ol><h2 id="方式-c-手动-git-macos-linux-进阶" tabindex="-1">方式 C：手动 Git（macOS / Linux / 进阶） <a class="header-anchor" href="#方式-c-手动-git-macos-linux-进阶" aria-label="Permalink to &quot;方式 C：手动 Git（macOS / Linux / 进阶）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Comfy-Org/ComfyUI.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ComfyUI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows: venv\\Scripts\\activate</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.txt</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 按显卡安装匹配的 PyTorch（见 PyTorch 官网）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span></span></code></pre></div><h2 id="开启局域网-连手机必做" tabindex="-1">开启局域网（连手机必做） <a class="header-anchor" href="#开启局域网-连手机必做" aria-label="Permalink to &quot;开启局域网（连手机必做）&quot;">​</a></h2><h3 id="便携包-命令行" tabindex="-1">便携包 / 命令行 <a class="header-anchor" href="#便携包-命令行" aria-label="Permalink to &quot;便携包 / 命令行&quot;">​</a></h3><p>编辑启动脚本（如 <code>run_nvidia_gpu.bat</code>），在 <code>main.py</code> 后增加：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--listen</span></span></code></pre></div><p>完整示例：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\python_embeded\\python.exe -s ComfyUI\\main.py --windows-standalone-build --listen</span></span></code></pre></div><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>--listen</code></td><td>无参数时监听所有网卡，允许局域网访问</td></tr><tr><td><code>--port 8188</code></td><td>可选改端口</td></tr><tr><td><code>--enable-cors-header</code></td><td>浏览器跨域需要时再加；手机 App 直连 API 通常不必</td></tr></tbody></table><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><p>见上文：Listen 设为 <code>0.0.0.0</code>，端口以界面为准。</p><h2 id="放置模型" tabindex="-1">放置模型 <a class="header-anchor" href="#放置模型" aria-label="Permalink to &quot;放置模型&quot;">​</a></h2><p>将 checkpoint（<code>.safetensors</code>）放入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ComfyUI/models/checkpoints/</span></span></code></pre></div><p>在界面中按 <code>R</code> 刷新模型列表，或重启。先确保能在 ComfyUI 网页里手动跑通默认文生图，再连 App。</p><p>模型来源示例：<a href="https://civitai.com/" target="_blank" rel="noreferrer">Civitai</a> · <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a>。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>本机：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8188</span></span></code></pre></div><p>局域网（换成电脑 IP；Desktop 注意端口）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.x.x:8188</span></span></code></pre></div><p>手机浏览器能打开同一地址，说明网络与监听正常。</p><h2 id="与-minitavern-的差异-请先读" tabindex="-1">与 MiniTavern 的差异（请先读） <a class="header-anchor" href="#与-minitavern-的差异-请先读" aria-label="Permalink to &quot;与 MiniTavern 的差异（请先读）&quot;">​</a></h2><ul><li>App 使用<strong>内置默认 workflow</strong>，一般会选用你机器上可用的 checkpoint；复杂自定义节点图需自行改服务端，不在本教程范围。</li><li>当前版本默认 Comfy 流程<strong>不使用参考图</strong>（有参考图也不会报错）；需要参考图锁脸时请用 <a href="./a1111">A1111</a> 或支持参考图的云端平台。</li><li>电脑休眠、合盖后服务会停；IP 变更后需在 App 里改 Base URL。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./connect-app">在 MiniTavern 中配置</a></li><li>总览：<a href="./index">生图模型部署</a></li></ul>`,36)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
